package com.crm.fees;
import com.crm.fees.service.*;import com.crm.fees.dto.FeeCycleContracts.*;import com.crm.fees.repository.*;import com.crm.fees.entity.*;import com.crm.security.AuthenticatedUserPrincipal;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;import org.junit.jupiter.api.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.data.domain.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class FeeCyclePolicyTest {
 FeeOfferingRepository offers;FeeTariffRepository rates;FeeTimeRepository times;FeeRepository fees;FeeReferenceDirectory directory;FeeCycleService service;FeeOffering offer;FeeTariff rate;FeeTimeEntry entry;
 static void role(String role){var roles=List.of(new SimpleGrantedAuthority("ROLE_"+role));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"synthetic",roles),null,roles));}
 @BeforeEach void setup(){role("ADMIN");offers=mock(FeeOfferingRepository.class);rates=mock(FeeTariffRepository.class);times=mock(FeeTimeRepository.class);fees=mock(FeeRepository.class);directory=mock(FeeReferenceDirectory.class);service=new FeeCycleService(offers,rates,times,fees,directory);offer=new FeeOffering();offer.setId(7L);offer.setTitle("Consulting");offer.setEmployeeId("101");offer.setCustomerId("202");offer.setCurrency("TND");when(offers.lock(7L)).thenReturn(Optional.of(offer));when(offers.findById(7L)).thenReturn(Optional.of(offer));
  rate=new FeeTariff();rate.setId(8L);rate.setOfferingId(7L);rate.setRate(new BigDecimal("12.34"));rate.setValidFrom(LocalDate.parse("2026-01-01"));rate.setValidTo(LocalDate.parse("2026-12-31"));when(rates.findById(8L)).thenReturn(Optional.of(rate));when(rates.applicable(eq(7L),any(),any())).thenReturn(List.of(rate));
  when(times.saveAndFlush(any())).thenAnswer(c->{entry=c.getArgument(0);entry.setId(9L);entry.setCreatedAt(java.time.LocalDateTime.now());return entry;});when(times.findById(9L)).thenAnswer(c->Optional.ofNullable(entry));when(fees.saveAndFlush(any())).thenAnswer(c->{Fee fee=c.getArgument(0);fee.setId(10L);when(fees.findById(10L)).thenReturn(Optional.of(fee));return fee;});when(rates.saveAndFlush(any())).thenAnswer(c->{FeeTariff t=c.getArgument(0);t.setId(11L);return t;});when(offers.saveAndFlush(any())).thenAnswer(c->{FeeOffering o=c.getArgument(0);o.setId(12L);return o;});}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 NewTime input(){return new NewTime(UUID.randomUUID().toString(),LocalDate.parse("2026-11-05"),new BigDecimal("2.50"),"Design");}
 TariffInput tariff(){return new TariffInput(new BigDecimal("15"),LocalDate.parse("2027-01-01"),null,true);}
 void create(){service.createTime(7L,input(),"Bearer test");}
 @Test void createsOfferingWithVerifiedReferencesAndExplicitCurrency(){var r=service.createOffering(new OfferingInput("Work","101","202","EUR"),"Bearer test");assertEquals("EUR",r.currency());verify(directory).validate("101","202","Bearer test");}
 @Test void offeringReferencesCannotBeSuppliedThroughTimeInput(){create();verify(directory).validate("101","202","Bearer test");assertEquals(7L,entry.getOfferingId());assertEquals(42L,entry.getCreatedBy());}
 @Test void tariffCreationAllowsOpenEndedPeriodUnderParentLock(){service.createTariff(7L,tariff());var order=inOrder(offers,rates);order.verify(offers).lock(7L);order.verify(rates).overlaps(eq(7L),eq(0L),eq(LocalDate.parse("2027-01-01")),eq(LocalDate.of(9999,12,31)));order.verify(rates).saveAndFlush(any());}
 @Test void overlappingActiveTariffIsRejected(){when(rates.overlaps(anyLong(),anyLong(),any(),any())).thenReturn(1L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.createTariff(7L,tariff()));verify(rates,never()).saveAndFlush(any());}
 @Test void reversedTariffPeriodIsRejected(){assertThrows(IllegalArgumentException.class,()->service.createTariff(7L,new TariffInput(BigDecimal.ONE,LocalDate.parse("2026-02-01"),LocalDate.parse("2026-01-01"),true)));}
 @Test void unusedTariffCanBeEdited(){service.updateTariff(8L,tariff());assertEquals(new BigDecimal("15"),rate.getRate());assertNull(rate.getValidTo());}
 @Test void usedTariffCannotBeMutatedButCanBeDeactivated(){when(times.existsByTariffId(8L)).thenReturn(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateTariff(8L,tariff()));assertEquals(new BigDecimal("12.34"),rate.getRate());service.tariffActive(8L,false);assertFalse(rate.isActive());}
 @Test void tariffReactivationChecksForNewOverlap(){rate.setActive(false);when(rates.overlaps(anyLong(),anyLong(),any(),any())).thenReturn(1L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.tariffActive(8L,true));assertFalse(rate.isActive());}
 @Test void timeCapturesAppliedRateAndAmount(){var t=service.createTime(7L,input(),"Bearer test");assertEquals(new BigDecimal("30.85"),t.amount());assertEquals(new BigDecimal("12.34"),t.appliedRate());assertEquals("8",t.tariffId());}
 @Test void absentOrAmbiguousTariffFailsClosed(){when(rates.applicable(anyLong(),any(),any())).thenReturn(List.of());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->create());when(rates.applicable(anyLong(),any(),any())).thenReturn(List.of(rate,rate));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->create());verify(times,never()).saveAndFlush(any());}
 @Test void rateSelectionUsesWorkDateNotToday(){create();verify(rates).applicable(eq(7L),eq(LocalDate.parse("2026-11-05")),argThat(p->p.getPageSize()==2));}
 @Test void invalidHoursAndProductOverflowAreRejected(){var bad=new NewTime(UUID.randomUUID().toString(),LocalDate.now(),new BigDecimal("-1"),"Work");assertThrows(IllegalArgumentException.class,()->service.createTime(7L,bad,"Bearer test"));rate.setRate(FeeFinance.MAX);assertThrows(IllegalArgumentException.class,()->create());verify(times,never()).saveAndFlush(any());}
 @Test void manifestDuplicateTimeIsRejected(){when(times.existsByActiveSignatureAndIdNot(anyString(),anyLong())).thenReturn(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->create());verify(times,never()).saveAndFlush(any());}
 @Test void repeatedCreationWithSameIdentityIsIdempotent(){var i=input();service.createTime(7L,i,"Bearer test");when(times.findByRequestId(i.requestId())).thenReturn(Optional.of(entry));service.createTime(7L,i,"Bearer test");verify(times,times(1)).saveAndFlush(any());}
 @Test void reusedIdentityWithDifferentHoursIsRejected(){var i=input();create();when(times.findByRequestId(i.requestId())).thenReturn(Optional.of(entry));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.createTime(7L,new NewTime(i.requestId(),i.workDate(),BigDecimal.ONE,"Design"),"Bearer test"));}
 @Test void descriptiveEditKeepsHistoricalRateWithoutARecalculation(){create();rate.setRate(new BigDecimal("999"));service.updateTime(9L,new TimeInput(entry.getWorkDate(),entry.getHours(),"Description rectified"),"Bearer test");assertEquals(new BigDecimal("30.85"),entry.getAmount());verify(rates,times(1)).applicable(anyLong(),any(),any());}
 @Test void changingDurationExplicitlyRecalculatesAndChecksReferences(){create();service.updateTime(9L,new TimeInput(entry.getWorkDate(),new BigDecimal("3"),"Design"),"Bearer test");assertEquals(new BigDecimal("37.02"),entry.getAmount());verify(directory,times(2)).validate("101","202","Bearer test");}
 @Test void cancellationPreservesHistoryAndReleasesDuplicateSignature(){create();service.cancelTime(9L,"Wrong date");assertTrue(entry.isCancelled());assertEquals("Wrong date",entry.getCancelReason());assertNull(entry.getActiveSignature());assertEquals(new BigDecimal("30.85"),entry.getAmount());}
 @Test void cancelledTimeCannotBePostedOrEdited(){create();service.cancelTime(9L,"Wrong");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.post(9L,"Bearer test"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateTime(9L,new TimeInput(LocalDate.now(),BigDecimal.ONE,"Work"),"Bearer test"));}
 @Test void recordingCreatesOneFeeWithFrozenExactSnapshot(){create();var fee=service.post(9L,"Bearer test");assertEquals(new BigDecimal("2.50"),fee.getExactHours());assertEquals(new BigDecimal("30.85"),fee.getAmount());assertEquals("TND",fee.getCurrency());assertEquals(9L,fee.getSourceTimeId());assertNull(fee.getInvoiceStatus());service.post(9L,"Bearer test");verify(fees,times(1)).saveAndFlush(any());}
 @Test void recordedTimeCannotBeChangedOrCancelled(){create();service.post(9L,"Bearer test");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.updateTime(9L,new TimeInput(LocalDate.now(),BigDecimal.ONE,"Work"),"Bearer test"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.cancelTime(9L,"Wrong"));}
 @Test void inactiveOfferingKeepsHistoryButPreventsNewTimesAndTariffs(){offer.setActive(false);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->create());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.createTariff(7L,tariff()));}
 @Test void datesAndPagingAreBounded(){assertThrows(IllegalArgumentException.class,()->service.times(7L,LocalDate.parse("2026-01-01"),LocalDate.parse("2027-01-02"),0));assertThrows(IllegalArgumentException.class,()->service.offerings("",-1));}
 @Test void personalRolesCannotReadOrWriteCycleData(){for(String role:List.of("EMPLOYEE","CLIENT")){role(role);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.offerings("",0));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.createTariff(7L,tariff()));}verifyNoInteractions(offers,rates,times);}
 @Test void lockIsSharedByTariffAndTimeOperations(){create();var order=inOrder(offers,rates,times);order.verify(offers).lock(7L);order.verify(times).findByRequestId(anyString());order.verify(rates).applicable(anyLong(),any(),any());order.verify(times).saveAndFlush(any());}
}